package server

import "github.com/Autumn-27/artex/config"

// Catalog that substitutes user-facing backend messages (Korean originals) with the active output language. In this repo the
// writeErr response text and some writeJSON error fields are written as Korean constants/literals (F3b/F34).
// Here those Korean originals are the keys and the English, Chinese and Spanish translations are the values. Korean (ko) is
// the key itself, so it is not stored; on lookup failure or when ko, the original is returned as-is.
//
// Keys are generated by extracting, byte for byte, the Korean constants/literals from the source (a scripts helper). Since they are not
// typed by hand, there is no case where a key diverges from the runtime value passed to writeErr and is silently missed.
//
// Format-string constants (%d, %s, %w, etc.) produce formatted results that differ from the key, so before the caller passes them to fmt.Sprintf/
// fmt.Errorf, it must first substitute the template itself with trMsg(template).

// trMsg substitutes a Korean original message with the active output language. If it is not in the catalog or the active language is
// Korean, the original is returned as-is. config.ActiveLanguage reflects the runtime setting (settings table),
// so the language the user picks takes effect immediately.
func trMsg(ko string) string {
	if m, ok := errCatalog[ko]; ok {
		if v, ok2 := m[config.ActiveLanguage()]; ok2 && v != "" {
			return v
		}
	}
	return ko
}

// logT translates an operator-facing console log template (config.T) so server
// log.Printf sites can wrap a template without each file importing config.
func logT(ko string) string { return config.T(ko) }

// loadOutputLanguage resolves the user-facing output language from the source of
// truth: the runtime setting (settings table) over config.Language() (ARTEX_LANG >
// config file > ko). Call it only to (re)fill the cache; it does a DB query and a
// config file read.
func (s *Server) loadOutputLanguage() string {
	if s.m != nil && s.m.pg != nil {
		if v, ok, _ := s.m.pg.GetSetting(settingOutputLanguage); ok {
			if nv := config.NormalizeLanguage(v); nv != "" {
				return nv
			}
		}
	}
	return config.Language()
}

// outputLanguage returns the cached output language, resolving it on first use.
func (s *Server) outputLanguage() string {
	if v, ok := s.outputLang.Load().(string); ok && v != "" {
		return v
	}
	v := s.loadOutputLanguage()
	s.outputLang.Store(v)
	return v
}
